@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<div class="kanban-board">
    @if (isLoading)
    {
        <div class="board-loading">Loading tasks...</div>
    }
    else if (errorMessage is not null)
    {
        <div class="board-error">
            <p>@errorMessage</p>
            <button @onclick="LoadTasks">Retry</button>
        </div>
    }
    else
    {
        <BoardStats Tasks="allTasks" />

        <div class="board-search">
            <input type="text"
                   placeholder="Search tasks by title..."
                   @bind="searchText"
                   @bind:event="oninput"
                   class="search-input" />
        </div>

        <div class="kanban-columns">
            <KanbanColumn ColumnName="To Do"
                          Tasks="GetFilteredTasks("To Do")"
                          ShowMoveLeft="false"
                          ShowMoveRight="true"
                          OnMoveRight="MoveRight"
                          OnAddTask="@(t => AddTask(t, "To Do"))" />

            <KanbanColumn ColumnName="In Progress"
                          Tasks="GetFilteredTasks("In Progress")"
                          ShowMoveLeft="true"
                          ShowMoveRight="true"
                          OnMoveLeft="MoveLeft"
                          OnMoveRight="MoveRight"
                          OnAddTask="@(t => AddTask(t, "In Progress"))" />

            <KanbanColumn ColumnName="Done"
                          Tasks="GetFilteredTasks("Done")"
                          ShowMoveLeft="true"
                          ShowMoveRight="false"
                          OnMoveLeft="MoveLeft"
                          OnAddTask="@(t => AddTask(t, "Done"))" />
        </div>
    }
</div>

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Columns = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private async Task MoveRight(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Columns, task.Status);
        if (currentIndex < Columns.Length - 1)
        {
            var newStatus = Columns[currentIndex + 1];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
    }

    private async Task MoveLeft(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Columns, task.Status);
        if (currentIndex > 0)
        {
            var newStatus = Columns[currentIndex - 1];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
    }

    private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) newTask, string status)
    {
        var created = await TaskService.CreateTaskAsync(newTask.Title, newTask.Assignee, newTask.Priority, newTask.DueDate);
        allTasks.Add(created with { Status = status });
    }
}

